import Foundation
public struct DriveshaftSpecification: Codable,Hashable,Sendable { public var lengthM=1.42,outerDiameterM=0.0762,wallM=0.00165,youngsModulusPa=210e9,densityKgM3=7850.0,bearingSupportFactor=1.0,baselineUJointAngleRad=0.052;public init(){} }
public struct DriveshaftResonanceState: Codable,Hashable,Sendable { public var uJointFatigue01=0.0,peakDeflectionMm=0.0;public init(){} }
public struct DriveshaftResonanceOutput: Codable,Hashable,Sendable { public var criticalRPM:Double,resonanceRatio:Double,estimatedDeflectionMm:Double,uJointFatigue01:Double,fractureRisk01:Double }
public enum DriveshaftResonanceAuthority { public static func step(state:inout DriveshaftResonanceState,spec:DriveshaftSpecification = .init(),shaftRPM:Double,torqueNm:Double,chassisTwistDeg:Double,dt:Double)->DriveshaftResonanceOutput { let ro=spec.outerDiameterM/2,ri=max(0,ro-spec.wallM),i=Double.pi/4*(pow(ro,4)-pow(ri,4)),a=Double.pi*(ro*ro-ri*ri);let omega=pow(Double.pi/spec.lengthM,2)*sqrt(spec.youngsModulusPa*i/(spec.densityKgM3*a))*spec.bearingSupportFactor;let critical=omega*60/(2*Double.pi),ratio=abs(shaftRPM)/max(1,critical),den=max(0.06,abs(1-ratio*ratio)),defl=ratio>0.65 ? abs(torqueNm)/400*ratio/den*0.18:0;let angle=spec.baselineUJointAngleRad+abs(chassisTwistDeg)*Double.pi/360;state.uJointFatigue01=min(1,state.uJointFatigue01+max(0,angle-0.07)*abs(shaftRPM)/5000*max(0,dt)/500);state.peakDeflectionMm=max(state.peakDeflectionMm,defl);let risk=min(1,max(0,(ratio-0.82)/0.35)+max(0,defl-12)/30+state.uJointFatigue01*0.3);return .init(criticalRPM:critical,resonanceRatio:ratio,estimatedDeflectionMm:defl,uJointFatigue01:state.uJointFatigue01,fractureRisk01:risk)} }
